def decode_abbreviation(abbr):
    base_year = 1989
    year_length = len(abbr) - 4  # Remove 'IAO'' from the length
    year_str = abbr[4:]  # Extract the digits part
    year = int(year_str)  # Convert the digits to an integer
    return base_year + year  # Calculate the full year

def main():
    n = int(input())
    abbreviations = [input().strip() for _ in range(n)]
    for abbr in abbreviations:
        print(decode_abbreviation(abbr))

if __name__ == "__main__":
    main()
